      let hueSum =
        w0 * u.mixerHue0.x + w1 * u.mixerHue0.y + w2 * u.mixerHue0.z + w3 * u.mixerHue0.w +
        w4 * u.mixerHue1.x + w5 * u.mixerHue1.y + w6 * u.mixerHue1.z + w7 * u.mixerHue1.w;
